message.content:
{
  "definition_simple": "在体育比赛或竞技活动中负责执行规则、裁决胜负的人。",
  "definition_standard": "依据既定竞赛规程与规则，在各类体育或竞技活动中独立行使监督、评判与裁决职能的专业执法人员。",
  "pos": "名词",
  "semantic_class": "concrete",
  "sentences": [
    {
      "tier": "T1",
      "sentence": "裁判吹响了比赛结束的哨声。"
    },
    {
      "tier": "T1",
      "sentence": "足球比赛需要一名主裁判和两名助理裁判。"
    },
    {
      "tier": "T2",
      "sentence": "运动员必须无条件服从裁判的判决。"
    },
    {
      "tier": "T2",
      "sentence": "看到裁判出示黄牌，防守队员激动地跑过去申诉。"
    },
    {
      "tier": "T3",
      "sentence": "这场焦点战对裁判的心理素质和控场能力是极大的考验。"
    },
    {
      "tier": "T3",
      "sentence": "赛后新闻发布会上，双方教练均对裁判在关键时刻的漏判表达了不满。"
    },
    {
      "tier": "T4",
      "sentence": "随着视频助理裁判技术的引入，赛场关键争议判罚的发生率大幅降低。"
    },
    {
      "tier": "T5",
      "sentence": "国际体育组织对涉嫌在淘汰赛阶段操纵判罚的裁判团队启动了停职调查。"
    },
    {
      "tier": "T5",
      "sentence": "多名资深执法人员因违规接受利益输送被起诉，直接促使联赛重组了裁判委员会。"
    },
    {
      "tier": "T6",
      "sentence": "仲裁法庭最终裁定，裁判在未依规调阅传感系统实存数据的情况下径行终结赛事，已构成重大裁量过失。"
    }
  ],
  "morphological_forms": [
    {
      "form": "裁判员",
      "label": "agentive_suffix"
    },
    {
      "form": "裁判长",
      "label": "leader_official_suffix"
    }
  ],
  "morphology_wrong_forms": {
    "裁判员": [
      {
        "wrong_form": "裁判者",
        "explanation": "现代汉语中虽然'-者'可表示人，但体育竞技体系中的正式从业人员后缀固定使用'-员'，'裁判者'不符合行业规范称谓。"
      },
      {
        "wrong_form": "裁判生",
        "explanation": "错误类比'学生'或'考生'添加后缀'-生'，裁判是具备资格资质的成年执法人员，不能使用具有学徒、受试含义的'-生'。"
      },
      {
        "wrong_form": "裁判家",
        "explanation": "错误套用表示学术或艺术名家的后缀'-家'，裁判属于规则执行岗位，不能赋予学术尊称后缀。"
      }
    ],
    "裁判长": [
      {
        "wrong_form": "裁判主",
        "explanation": "错误套用'车主/店主'的'-主'后缀，汉语中表示执法团队负责人的层级职衔应使用'-长'而非'-主'。"
      },
      {
        "wrong_form": "裁判头",
        "explanation": "误加带有口语俗语色彩的后缀'-头'，违背了正规赛事职衔的庄重书面规范。"
      },
      {
        "wrong_form": "裁判官长",
        "explanation": "生造叠加古代职官词素'官'与现代职衔'长'，属于冗余且不规范的造词。"
      }
    ]
  },
  "l1_audio_confusables": [
    {
      "word": "采办",
      "explanation": "发音与'裁判'仅在第一字声调（上声cǎi与阳平cái）和第二字送气与否（不送气bàn与送气pàn）上存在微小差异，极易在口语语流中听混。"
    },
    {
      "word": "彩排",
      "explanation": "第一字声调不同（cǎi与cái），第二字韵母相近但存在鼻音差别（pái与pàn），听觉感知上的音响轮廓高度相似。"
    },
    {
      "word": "踩盘",
      "explanation": "音节成分完全相同，仅声调存在差异（cǎi pán与cái pàn），在说话人音调不准时极易引发听觉误判。"
    }
  ],
  "primary_collocate": "主裁判",
  "collocation_distractors": [
    {
      "word": "律法裁判",
      "explanation": "法律审判语境中的正式人员为主审法官或审判长，'律法'不与'裁判'进行固定搭配。"
    },
    {
      "word": "审理裁判",
      "explanation": "'审理'通常与司法案件、法庭活动搭配，不能直接作为前置定语修饰作为体育执法人员的'裁判'。"
    },
    {
      "word": "执法教练",
      "explanation": "概念范畴混淆，教练负责指导队伍战术，裁判负责执行规则，二者不能混合构成修饰搭配。"
    }
  ],
  "collocation_wrong_collocate": "掌勺裁判",
  "cloze_distractors": [
    {
      "word": "教练",
      "explanation": "语义混淆：教练是主导队伍训练和制定战术的人，而非在场上执掌规则评定胜负的人。"
    },
    {
      "word": "观众",
      "explanation": "角色错位：观众是观摩比赛的群体，无权对赛场动作做出裁判性判罚。"
    },
    {
      "word": "判官",
      "explanation": "语域与文体错误：'判官'多用于古代官署或民间神话传说，现代体育竞赛中不能使用该词代指裁判。"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "被告人在法庭上听取了裁判宣读的最终判决书。",
      "explanation": "语域混淆：法庭司法审判中行使审判权的公职人员应为'法官'或'审判长'，不可使用偏向体育竞赛执法者的'裁判'。"
    },
    {
      "sentence": "他在这次演讲比赛中表现优异，被评委裁判为最佳选手。",
      "explanation": "句式与动词论元结构错误：现代汉语中'裁判'作为动词时不具备带双宾语或'使役定名'（裁判为……）的结构功能，此处应使用'评定为'或'评选为'。"
    },
    {
      "sentence": "比赛结束后，队长裁判地向看台上的球迷挥手致意。",
      "explanation": "词性与句法误用：'裁判'在此处被误当作描摹态度的状语修饰动词'挥手'，属于严重的词类误用。"
    }
  ],
  "spot_incorrect": {
    "sentence": "这场争议点球的判决引发了轩然大波，赛后组委会宣布涉事裁判官将被无限期停赛。",
    "error_description": "体育执法人员的规范称谓为'裁判'或'裁判员'，混用古汉语官职后缀生造出不合规范的'裁判官'。",
    "corrected_sentence": "这场争议点球的判决引发了轩然大波，赛后组委会宣布涉事裁判员将被无限期停赛。"
  },
  "word_family_forms": [
    {
      "form": "裁判权",
      "pos": "名词",
      "meaning": "依规则在竞赛中进行裁决的合法权力。"
    },
    {
      "form": "裁判席",
      "pos": "名词",
      "meaning": "竞赛场边供裁判人员就座与记录的专门工作区域。"
    }
  ],
  "word_family_fake_forms": [
    {
      "form": "裁判度",
      "explanation": "仿造'准确度/灵敏度'生造的词，现代汉语中并无表示裁判尺度或公信力高低的'裁判度'一词。"
    },
    {
      "form": "裁判化",
      "explanation": "仿造'-化'后缀生造，企图表达规则仲裁机制的普及，但该派生词在词汇系统中并不存在。"
    },
    {
      "form": "裁判力",
      "explanation": "仿造'控制力/执行力'生造，试图指代裁判掌控比赛的能力，不属于规范汉语词汇。"
    }
  ],
  "syn_ant_candidates": [
    {
      "word": "裁判员",
      "relation": "synonym"
    },
    {
      "word": "公断人",
      "relation": "synonym"
    },
    {
      "word": "运动员",
      "relation": "antonym"
    },
    {
      "word": "参赛者",
      "relation": "antonym"
    }
  ],
  "particle_candidates": null
}
